create extension if not exists pgcrypto;
create table insurers(id uuid primary key default gen_random_uuid(),name text not null,license_no text,status text default 'active',created_at timestamptz default now());
create table users(id uuid primary key default gen_random_uuid(),phone varchar(15) unique not null,email text,role text not null check(role in('worker','client','insurer','admin')),kyc text default 'pending',reputation numeric(6,2) default 0,insurer_id uuid references insurers(id),created_at timestamptz default now());
create table otp_codes(id uuid primary key default gen_random_uuid(),phone varchar(15) not null,code_hash text not null,attempts int default 0,used bool default false,expires_at timestamptz not null);
create table worker_profiles(user_id uuid primary key references users(id),full_name text,county text,id_number_hash text,bio text,available bool default true);
create table sectors(id text primary key,name text not null,min_rate int,max_rate int,std_hours int,req_gps bool,req_photo bool,req_signature bool);
create table skills(id text primary key,sector_id text references sectors(id),name text,level text);
create table verification_records(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),skill_id text references skills(id),phase int default 1,score numeric(5,2),status text default 'pending' check(status in('pending','passed','failed','expired')),credential_ref text,reviewer_id uuid,expires_at timestamptz,created_at timestamptz default now());
create table policies(id uuid primary key default gen_random_uuid(),insurer_id uuid references insurers(id),policy_ref text,holder_phone varchar(15),sector_id text references sectors(id),cover_amount numeric(12,2),status text default 'active');
create table active_problems(id uuid primary key default gen_random_uuid(),title text not null,description text,sector_id text references sectors(id),severity text default 'medium',lat double precision,lng double precision,source text default 'manual',bounty numeric(12,2),status text default 'detected',created_by uuid references users(id),created_at timestamptz default now());
create table claims(id uuid primary key default gen_random_uuid(),insurer_id uuid references insurers(id),policy_ref text,problem_id uuid references active_problems(id),amount numeric(12,2),status text default 'received',created_at timestamptz default now());
create table dispatches(id uuid primary key default gen_random_uuid(),problem_id uuid references active_problems(id),worker_id uuid references users(id),status text default 'assigned',created_at timestamptz default now());
create table contracts(id uuid primary key default gen_random_uuid(),problem_id uuid references active_problems(id),claim_id uuid references claims(id),worker_id uuid references users(id),payer_id uuid references users(id),sector_id text references sectors(id),total numeric(12,2),fee numeric(12,2),status text default 'pending' check(status in('pending','funded','in_progress','proof_submitted','released','disputed','refunded')),created_at timestamptz default now());
create table escrow_transactions(id uuid primary key default gen_random_uuid(),contract_id uuid references contracts(id),kind text check(kind in('funding','payout','refund')),amount numeric(12,2),checkout_id text,mpesa_ref text,status text default 'pending',created_at timestamptz default now());
create table proofs(id uuid primary key default gen_random_uuid(),contract_id uuid references contracts(id),lat double precision,lng double precision,photo_url text,signature text,created_at timestamptz default now());
create table disputes(id uuid primary key default gen_random_uuid(),contract_id uuid references contracts(id),raised_by uuid references users(id),reason text,status text default 'open',outcome text,resolved_by uuid,created_at timestamptz default now());
create table reputation_events(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),delta numeric(4,1),reason text,ref_id uuid,created_at timestamptz default now());
create table audit_trail(seq bigserial primary key,actor_id uuid,action text not null,entity_type text,entity_id uuid,prev_state jsonb,new_state jsonb,prev_hash text,hash text,created_at timestamptz default now());
create table webhook_events(id uuid primary key default gen_random_uuid(),source text,payload jsonb,created_at timestamptz default now());
create table fee_schedule(id serial primary key,sector_id text references sectors(id),fee_pct numeric(4,2) default 3,active bool default true);
create table notifications(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),body text,read bool default false,created_at timestamptz default now());
create index on active_problems(sector_id,status);create index on contracts(worker_id,status);create index on verification_records(user_id,status);
create function no_mut() returns trigger as $$ begin raise exception 'audit_trail is append-only'; end $$ language plpgsql;
create trigger audit_ro before update or delete on audit_trail for each row execute function no_mut();
